                peso = peso.add(pesoUnitario.multiply(quantidade));
            }
        }
        return peso;
    }

    private BigDecimal extrairCreditoDoResumo(Pedido pedido) {
        try {
            return new BigDecimal(pedido.getResumo().get("creditoProximaCompra").asText());
        } catch (Exception e) {
            return BigDecimal.ZERO;
        }
    }
}

