        }
        return 0;
    }

    private BigDecimal calcularSeguro(BigDecimal subtotal, String regiao) {
        BigDecimal percentual;
        BigDecimal limite = null;

        switch (regiao) {
            case "SUDESTE":
            case "SUL":
                percentual = new BigDecimal("1");
                break;
